changeSet.sql:
ALTER TABLE clinlims.master_data_identity
  ADD CONSTRAINT chk_master_identity_type CHECK (entity_type IN ('TEST','SAMPLE_TYPE','ORGANIZATION','PROVIDER')),
  ADD CONSTRAINT chk_master_identity_one_reference CHECK (num_nonnulls(test_id, sample_type_id, organization_id, provider_id) = 1),
  ADD CONSTRAINT chk_master_identity_reference_matches_type CHECK (
    (entity_type = 'TEST' AND test_id IS NOT NULL) OR
    (entity_type = 'SAMPLE_TYPE' AND sample_type_id IS NOT NULL) OR
    (entity_type = 'ORGANIZATION' AND organization_id IS NOT NULL) OR
    (entity_type = 'PROVIDER' AND provider_id IS NOT NULL)),
  ADD CONSTRAINT chk_master_identity_validity CHECK (valid_to IS NULL OR valid_from IS NULL OR valid_to >= valid_from),
  ADD CONSTRAINT chk_master_identity_code_nonblank CHECK (btrim(canonical_code) <> ''),
  ADD CONSTRAINT chk_master_identity_source_nonblank CHECK (btrim(source_system) <> '');

CREATE UNIQUE INDEX uq_master_identity_test ON clinlims.master_data_identity(test_id) WHERE test_id IS NOT NULL;
CREATE UNIQUE INDEX uq_master_identity_sample_type ON clinlims.master_data_identity(sample_type_id) WHERE sample_type_id IS NOT NULL;
CREATE UNIQUE INDEX uq_master_identity_organization ON clinlims.master_data_identity(organization_id) WHERE organization_id IS NOT NULL;
CREATE UNIQUE INDEX uq_master_identity_provider ON clinlims.master_data_identity(provider_id) WHERE provider_id IS NOT NULL;
CREATE UNIQUE INDEX uq_master_identity_code ON clinlims.master_data_identity(entity_type, upper(btrim(canonical_code)));
CREATE INDEX idx_master_identity_status ON clinlims.master_data_identity(entity_type, valid_from, valid_to);

CREATE OR REPLACE FUNCTION clinlims.capture_master_data_identity_history()
RETURNS trigger AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'Master data identities cannot be deleted; set valid_to instead';
  END IF;
  IF NEW.entity_type IS DISTINCT FROM OLD.entity_type
     OR NEW.test_id IS DISTINCT FROM OLD.test_id
     OR NEW.sample_type_id IS DISTINCT FROM OLD.sample_type_id
     OR NEW.organization_id IS DISTINCT FROM OLD.organization_id
     OR NEW.provider_id IS DISTINCT FROM OLD.provider_id THEN
    RAISE EXCEPTION 'Master data identity target cannot be changed';
  END IF;
  INSERT INTO clinlims.master_data_identity_history
    (identity_id, entity_type, entity_id, canonical_code, source_system, valid_from, valid_to, changed_by)
  VALUES
    (OLD.id, OLD.entity_type, COALESCE(OLD.test_id, OLD.sample_type_id, OLD.organization_id, OLD.provider_id),
     OLD.canonical_code, OLD.source_system, OLD.valid_from, OLD.valid_to, NEW.updated_by);
  NEW.last_updated := CURRENT_TIMESTAMP;
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;
CREATE TRIGGER trg_master_data_identity_history
  BEFORE UPDATE OR DELETE ON clinlims.master_data_identity
  FOR EACH ROW EXECUTE FUNCTION clinlims.capture_master_data_identity_history();
